binfo->nbits = nbits;
constexpr std::size_t bits_per_group = sizeof(std::size_t) * 8;
std::size_t shift = 0;
while ((static_cast<std::size_t>(1) << shift) < bits_per_group) {
    ++shift;
}
binfo->shift = shift;
binfo->mask = bits_per_group - 1;
binfo->ngroups = (nbits + bits_per_group - 1) >> shift;

